    let b0_code_band_base = b0_band * words_per_row;
    let b0_scale_band_base = b0_band * groups_per_row;
    var b0_acc0 = 0.0; var b0_acc1 = 0.0; var b0_acc2 = 0.0; var b0_acc3 = 0.0;
    var b0_acc4 = 0.0; var b0_acc5 = 0.0; var b0_acc6 = 0.0; var b0_acc7 = 0.0;
