    let b1_scale_band_base = b1_band * groups_per_row;
    var b1_acc0 = 0.0; var b1_acc1 = 0.0; var b1_acc2 = 0.0; var b1_acc3 = 0.0;
    var b1_acc4 = 0.0; var b1_acc5 = 0.0; var b1_acc6 = 0.0; var b1_acc7 = 0.0;
//#endif
//#if Q1_BAND_GE32

